mapper.insert:
INSERT INTO users (
    login_id
  , email
  , pw_hash
  , pw_salt
  , user_name
  , user_phone
) VALUES (
    #{loginId}
  , #{email}
  , #{pwHash}
  , #{pwSalt}
  , #{userName}
  , #{userPhone}
)

mapper.update:
UPDATE users
   SET pw_hash = #{pwHash}
     , pw_salt = #{pwSalt}
     , updated_at = NOW()
 WHERE user_id = #{userId}

UPDATE users
   SET user_name = #{userName}
     , user_phone = #{userPhone}
     , birth_date = #{birthDate}
     , disability_type = #{disabilityType}
     , severity = #{severity}
     , updated_at = NOW()
 WHERE user_id = #{userId}

UPDATE users
   SET is_share_location = #{shareLocation}
     , is_share_result = #{shareResult}
     , is_sos_alert = #{sosAlert}
     , updated_at = NOW()
 WHERE user_id = #{userId}
